#!/usr/bin/env python3
"""Render multilingual scientific-scope indexes from the portable portfolio.

This is a documentation renderer, not a research worker or scientific gate.
It performs no network, model inference, installation, or publication.
"""
from pathlib import Path
import html, json

ROOT=Path(__file__).resolve().parents[1]
DATA=json.loads((ROOT/'reproducibility/portfolio.json').read_text())
CATEGORIES=['proofs','disproofs','partial-results','computational-papers']
LANG={
 'en':{'file':'README.md','name':'English','cats':['Proof','Disproof','Partial result','Computational result'],'intro':'An inspectable archive of AI-assisted physics research. **93 PDFs are preserved; 90 canonical research entries are indexed.** Three earlier results covered by later, more general or stronger claims remain linked as historical versions and are not counted twice. “10” is the name of the original collection, not the current manuscript count.','caution':'These are research drafts requiring human scientific, priority and authorship review. Recorded proof/disproof classes refer to the precise frozen claim. Partial and computational results leave the original problem unresolved. Separate AI review contexts are internal checks, not external peer review or journal acceptance. The original channel-boundariness draft retains its historical binding-gate limitation.','source_note':'Scientific statements and manuscript titles retain their source language. Navigation, status, usage and the original ten detailed descriptions are localized; quoted scientific claims are not silently translated or weakened.','browse':'Browse the four result classes','count':'Canonical entries','background':'Background / original question','scope':'Result and exact original-problem scope','novelty':'Proposed contribution','limits':'Limitations / bottlenecks','files':'PDF, source and replay','related':'Related results / preserved versions','status':'Original question','open':'unresolved','proved':'proved at the stated scope','disproved':'disproved at the stated scope','expand':'Click to expand the research table','all':'Searchable full catalog','relations':'Semantic comparison and deduplication','repro':'Reproduction guide','versions':'Earlier covered version; preserved and not counted independently','rights':'The act of packaging grants no additional license to manuscripts, code or data. Consult the original author handoff and applicable rights. No submission, peer-review or acceptance is implied.','workflow':'The supervised workflow checks primary sources, reconstructs equations independently, reproduces a published baseline, develops a bounded result, and uses a fresh internal referee before writing and release checks. Compact evidence-indexed handoffs and shared tools reduce repeated work; cached input is a subset of input, not additional usage. No unmeasured token savings or success rate is asserted.'},
 'zh-CN':{'file':'README.zh-CN.md','name':'中文','cats':['证明','反证','部分结果','计算结果'],'intro':'可检查的 AI 辅助物理研究档案。**保留 93 份 PDF，按 90 个规范研究条目索引。** 三项被后续更一般或更强结论覆盖的早期结果保留为关联历史版本，不重复计数。“10”沿用首批项目名称，不是当前论文数。','caution':'全部为待人类科学、新颖性和署名审核的研究草稿。证明、反证仅针对冻结命题的精确范围；部分结果、计算结果不表示原题完整解决。全新 AI 审查是内部检查，不是外部同行评审或期刊接收。原信道 boundariness 稿件仍保留历史绑定门禁缺口。','source_note':'科学命题和论文标题保留原文语言。导航、状态和使用说明已本地化，首批十篇保留原多语言详解；不会在翻译中悄悄改变数学范围。','browse':'按四大结果类别浏览','count':'规范条目','background':'物理背景 / 原始课题','scope':'结论及原题解决的精确范围','novelty':'拟议贡献与创新点','limits':'卡点、缺憾及适用限制','files':'PDF、源码与复现','related':'相关成果 / 保留的早期版本','status':'原题状态','open':'未解决','proved':'在所述范围内获证明','disproved':'在所述范围内被反例否定','expand':'点击展开研究表格','all':'可搜索完整成果总表','relations':'语义比较与去重记录','repro':'复现指南','versions':'被覆盖的早期版本；保留，不独立计数','rights':'整理入库不自动授予论文、代码或数据的额外许可。请查看原作者交接和适用权利说明；不表示投稿、同行评审或接收。','workflow':'监督流程核验一手原文，独立重建方程，复现发表基准，开展有界研究，再由全新内部审查角色核验后成文和发布检查。短证据索引、共用工具及语义去重减少重复工作；缓存输入属于输入的子集，不重复相加。不编造 token 节省比例或成功率。'},
 'de':{'file':'README.de.md','name':'Deutsch','cats':['Beweis','Widerlegung','Teilergebnis','Numerisches Ergebnis'],'intro':'Ein überprüfbares Archiv KI-gestützter Physikforschung. **93 PDFs bleiben erhalten; 90 kanonische Forschungseinträge werden indexiert.** Drei ältere Ergebnisse, die durch allgemeinere oder stärkere Aussagen abgedeckt sind, bleiben als verknüpfte historische Fassungen erhalten und werden nicht doppelt gezählt. „10“ bezeichnet die ursprüngliche Sammlung.','caution':'Alle Texte sind Forschungsentwürfe und benötigen menschliche Prüfung von Wissenschaft, Priorität und Autorenschaft. Beweis und Widerlegung gelten nur im exakt angegebenen Umfang. Teil- und numerische Ergebnisse lösen die ursprüngliche Frage nicht vollständig. Getrennte KI-Prüfkontexte sind interne Kontrollen, kein externes Peer-Review und keine Zeitschriftenannahme. Die historische Einschränkung der Bindungsprüfung des Boundariness-Entwurfs bleibt bestehen.','source_note':'Wissenschaftliche Aussagen und Titel bleiben in ihrer Quellsprache. Navigation, Status und Nutzung sowie die ursprünglichen zehn Beschreibungen sind lokalisiert; die mathematische Bedeutung der zitierten Aussagen bleibt unverändert.','browse':'Die vier Ergebnisklassen','count':'Kanonische Einträge','background':'Hintergrund / ursprüngliche Frage','scope':'Ergebnis und genauer Geltungsbereich','novelty':'Vorgeschlagener Beitrag','limits':'Grenzen / offene Schwierigkeiten','files':'PDF, Quelltext und Reproduktion','related':'Verwandte Ergebnisse / ältere Fassungen','status':'Ursprüngliche Frage','open':'ungelöst','proved':'im angegebenen Umfang bewiesen','disproved':'im angegebenen Umfang widerlegt','expand':'Forschungstabelle aufklappen','all':'Durchsuchbarer Gesamtkatalog','relations':'Semantischer Vergleich und Deduplizierung','repro':'Reproduktionsanleitung','versions':'Abgedeckte frühere Fassung; erhalten, nicht eigenständig gezählt','rights':'Die Zusammenstellung gewährt keine zusätzlichen Nutzungsrechte. Maßgeblich sind die ursprüngliche Autorenübergabe und die geltenden Rechte. Einreichung, Peer-Review oder Annahme werden nicht behauptet.','workflow':'Der überwachte Ablauf prüft Primärquellen, rekonstruiert Gleichungen unabhängig, reproduziert publizierte Referenzen und lässt begrenzte Ergebnisse vor Manuskript und Freigabe frisch intern prüfen. Kurze Evidenzpakete und gemeinsame Werkzeuge vermeiden Wiederholungen. Cache-Eingaben sind Teil der Eingaben; unbelegte Token-Einsparungen oder Erfolgsquoten werden nicht behauptet.'},
 'fr':{'file':'README.fr.md','name':'Français','cats':['Preuve','Réfutation','Résultat partiel','Résultat numérique'],'intro':'Une archive vérifiable de recherche en physique assistée par IA. **93 PDF sont conservés ; 90 entrées canoniques sont indexées.** Trois résultats antérieurs couverts par des conclusions plus générales ou plus fortes restent accessibles comme versions historiques, sans double comptage. « 10 » désigne la collection initiale.','caution':'Ce sont des manuscrits de recherche nécessitant une vérification humaine de la science, de la priorité et des auteurs. Preuve et réfutation concernent uniquement la portée exacte de la proposition figée. Les résultats partiels et numériques ne résolvent pas entièrement la question initiale. Les contextes IA séparés sont des contrôles internes, pas une évaluation externe ni une acceptation éditoriale. La limitation historique du contrôle de liaison du manuscrit sur la boundariness demeure.','source_note':'Les énoncés scientifiques et les titres gardent leur langue source. Navigation, statut, utilisation et les dix descriptions initiales sont localisés ; les affirmations citées ne sont pas modifiées par traduction.','browse':'Les quatre catégories de résultats','count':'Entrées canoniques','background':'Contexte / question initiale','scope':'Résultat et portée exacte','novelty':'Contribution proposée','limits':'Limites / difficultés restantes','files':'PDF, sources et reproduction','related':'Résultats liés / versions antérieures','status':'Question initiale','open':'non résolue','proved':'démontrée dans la portée indiquée','disproved':'réfutée dans la portée indiquée','expand':'Déplier le tableau de recherche','all':'Catalogue complet consultable','relations':'Comparaison sémantique et dédoublonnage','repro':'Guide de reproduction','versions':'Version antérieure couverte ; conservée, sans comptage indépendant','rights':'Le regroupement ne concède aucune licence supplémentaire. Consulter les instructions des auteurs et les droits applicables. Aucune soumission, évaluation externe ou acceptation n’est impliquée.','workflow':'Le processus supervisé vérifie les sources primaires, reconstruit indépendamment les équations, reproduit un résultat publié et fait contrôler chaque contribution limitée avant rédaction et validation. Des dossiers courts et des outils partagés réduisent les répétitions. Le cache est une partie de l’entrée ; aucune économie de tokens ou probabilité de succès non mesurée n’est annoncée.'},
 'ja':{'file':'README.ja.md','name':'日本語','cats':['証明','反証','部分結果','計算結果'],'intro':'検証可能な AI 支援物理研究アーカイブです。**93 件の PDF を保持し、90 件の代表研究項目を索引化しました。** 後の一般的・強い結果に含まれる初期の 3 件は関連する旧版として保持し、重複して数えません。「10」は最初のコレクション名です。','caution':'すべて人間による科学的内容、先取権、著者情報の確認が必要な研究草稿です。証明と反証は凍結された命題の明示範囲に限られます。部分結果・計算結果は元の問題の完全解決を意味しません。別の AI コンテキストでの審査は内部確認であり、外部査読や雑誌の採択ではありません。boundariness の旧草稿には過去の整合性ゲートの欠落が残ります。','source_note':'科学的命題と論文名は原文言語を保持します。ナビゲーション、状態、利用方法、および最初の十件の説明は現地語化され、引用命題の数学的範囲を翻訳で変更しません。','browse':'四つの結果分類','count':'代表項目数','background':'物理的背景 / 元の課題','scope':'結果と元の問題を解決した正確な範囲','novelty':'提案された貢献','limits':'制約 / 残る課題','files':'PDF・ソース・再現方法','related':'関連結果 / 保持された旧版','status':'元の問題の状態','open':'未解決','proved':'明示範囲で証明','disproved':'明示範囲で反証','expand':'研究表を展開','all':'検索可能な全成果一覧','relations':'意味に基づく比較・重複整理','repro':'再現ガイド','versions':'後の結果に含まれる旧版。保持し、独立には数えない','rights':'整理によって論文、コード、データへの追加の利用許諾は付与されません。著者引き継ぎと適用される権利を確認してください。投稿、外部査読、採択を意味しません。','workflow':'監督付きの工程は一次文献を確認し、方程式を独立に再構成し、公開済み基準を再現して、有界の研究を新しい内部審査に回します。短い証拠索引と共通ツールは反復を減らします。キャッシュ入力は入力の一部であり、未測定のトークン節約率や成功率は示しません。'},
 'ru':{'file':'README.ru.md','name':'Русский','cats':['Доказательство','Опровержение','Частичный результат','Вычислительный результат'],'intro':'Проверяемый архив исследований по физике с помощью ИИ. **Сохранены 93 PDF; проиндексированы 90 канонических исследовательских записей.** Три ранних результата, охваченных более общими или сильными утверждениями, сохранены как связанные исторические версии без двойного счёта. «10» — название исходной коллекции.','caution':'Это исследовательские черновики, требующие человеческой проверки науки, приоритета и авторства. Доказательства и опровержения относятся только к точной области зафиксированного утверждения. Частичные и вычислительные результаты не означают полного решения исходной задачи. Независимые контексты ИИ — внутренние проверки, а не внешнее рецензирование или принятие журналом. Исторический пробел проверки привязки рукописи о boundariness сохраняется.','source_note':'Научные утверждения и названия сохраняют язык источника. Навигация, статус, инструкции и исходные десять описаний локализованы; математический смысл цитируемых утверждений не меняется.','browse':'Четыре категории результатов','count':'Канонические записи','background':'Контекст / исходная задача','scope':'Результат и точная область утверждения','novelty':'Предлагаемый вклад','limits':'Ограничения / нерешённые трудности','files':'PDF, исходники и воспроизведение','related':'Связанные результаты / ранние версии','status':'Исходная задача','open':'не решена','proved':'доказана в указанной области','disproved':'опровергнута в указанной области','expand':'Развернуть исследовательскую таблицу','all':'Полный каталог с поиском','relations':'Семантическое сравнение и удаление дублей','repro':'Руководство по воспроизведению','versions':'Охваченная ранняя версия; сохранена без отдельного счёта','rights':'Упаковка не предоставляет дополнительных лицензий. См. исходные инструкции автора и применимые права. Подача, внешнее рецензирование или принятие не подразумеваются.','workflow':'Контролируемый процесс проверяет первоисточники, независимо восстанавливает уравнения, воспроизводит опубликованный эталон и передаёт ограниченный результат свежей внутренней проверке перед написанием и выпуском. Короткие пакеты доказательств и общие инструменты уменьшают повторы. Кэш — часть входа; неизмеренная экономия токенов или вероятность успеха не заявляется.'}
}

def table_escape(s):
    return str(s).replace('|','&#124;').replace('\n',' ').replace('[','\\[').replace(']','\\]')

def path(prefix,p): return prefix+p

def card(item,l,prefix=''):
    label=LANG[l];cat=label['cats'][CATEGORIES.index(item['category'])]
    parts=['<details>', '<summary><strong>'+html.escape(item['id']+' · '+item['title'])+'</strong> — '+cat+' · '+label['expand']+'</summary>','']
    if item.get('localized_legacy_details',{}).get(l):
        body=item['localized_legacy_details'][l].replace('(projects/','('+prefix+'projects/').replace('(reproducibility/','('+prefix+'reproducibility/')
        parts += [body,'']
    else:
        state=label['proved'] if item['original_status']=='proved' else label['disproved'] if item['original_status']=='disproved' else label['open']
        links='[PDF]('+path(prefix,item['pdf'])+') · [TeX]('+path(prefix,'projects/'+item['id']+'/manuscript/main.tex')+') · [Code / data]('+path(prefix,'projects/'+item['id'])+')'
        handoff=ROOT/'projects'/item['id']/'AUTHOR_HANDOFF.md'
        if handoff.is_file():links+=' · [Author handoff]('+path(prefix,'projects/'+item['id']+'/AUTHOR_HANDOFF.md')+')'
        guides=' · '.join('[Replay]('+path(prefix,'projects/'+item['id']+'/'+g)+')' for g in item.get('reproduction_guides',[]))
        parts+=['| | |','|---|---|', '| **'+label['background']+'** | '+table_escape(item['background'])+' |', '| **'+label['status']+'** | '+state+' |','| **'+label['scope']+'** | '+table_escape(item['claim_statement'])+' |','| **'+label['novelty']+'** | '+table_escape(item['novelty'])+' |','| **'+label['limits']+'** | '+table_escape(item['limitations'])+' |','| **'+label['files']+'** | '+links+(' · '+guides if guides else '')+' |','']
    if item.get('literature_note'):parts += ['> '+item['literature_note'],'']
    versions=item.get('related_versions',[]);related=item.get('related_results',[])
    if versions or related:
        parts+=['**'+label['related']+'**','']
        for v in versions:parts += ['- ['+v['id']+']('+path(prefix,'projects/'+v['id'])+'): '+label['versions']+'. '+v['reason']]
        for v in related:parts+=['- '+', '.join('['+i+']('+path(prefix,'projects/'+i)+')' for i in v['ids'])+': '+v['reason']]
        parts+=['']
    parts+=['</details>','']
    return '\n'.join(parts)

def make_readme(lang,category=None):
    l=LANG[lang];prefix='../../' if category else '';out=['# PROMETHEUS-10'+(' · '+l['cats'][CATEGORIES.index(category)] if category else ''),'','**AI Physics, Made Verifiable**','', ' · '.join('['+v['name']+']('+v['file']+')' for v in LANG.values()),'', l['intro'],'',l['caution'],'',l['source_note'],'']
    if category:out += ['[PROMETHEUS-10]('+prefix+l['file']+')','']
    out += ['['+l['all']+']('+prefix+'catalog.html) · ['+l['relations']+']('+prefix+'SEMANTIC_DEDUPLICATION.md) · ['+l['repro']+']('+prefix+'reproducibility/README.md)','', '## '+l['browse'],'','| | '+l['count']+' |','|---|---:|']
    for c in CATEGORIES:
        p=('../'+c+'/' if category else 'categories/'+c+'/')+l['file']
        out+=['| ['+l['cats'][CATEGORIES.index(c)]+']('+p+') | **'+str(DATA['counts'][c])+'** |']
    out+=['',l['workflow'],'']
    for c in ([category] if category else CATEGORIES):
        out+=['## '+l['cats'][CATEGORIES.index(c)],'']
        for i in DATA['projects']:
            if i['category']==c and i['counted_as_distinct']:out += [card(i,lang,prefix)]
    out+=['## Reproduction','', '```bash','python3 reproducibility/verify_portfolio.py','python3 reproducibility/verify_package.py','```','', l['rights'],'']
    return '\n'.join(out)

for lang,l in LANG.items():
    (ROOT/l['file']).write_text(make_readme(lang))
    for c in CATEGORIES:
        p=ROOT/'categories'/c;p.mkdir(parents=True,exist_ok=True);(p/l['file']).write_text(make_readme(lang,c))

payload=json.dumps(DATA,ensure_ascii=False).replace('<','\\u003c').replace('&','\\u0026')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PROMETHEUS-10 · Physics result catalog</title><style>body{max-width:1500px;margin:35px auto;padding:0 22px;font:15px/1.6 system-ui;color:#1d2b3f;background:#f6f8fc}h1{font-size:34px}input,select{font:inherit;padding:9px;border:1px solid #bac7da;border-radius:6px}input{width:43%}table{background:white;border-collapse:collapse;width:100%;margin-top:20px}th,td{border:1px solid #dce3ef;padding:12px;text-align:left;vertical-align:top}th{position:sticky;top:0;background:#e8eef7}td:first-child{min-width:170px}details{max-width:850px}summary{cursor:pointer}a{color:#175da6}.muted{color:#53637a}.badge{display:inline-block;padding:2px 6px;border-radius:4px;background:#edf1f7}pre{white-space:pre-wrap;word-break:break-word}.note{background:#fff7dd;padding:12px}button{font:inherit;padding:8px}</style><h1>PROMETHEUS-10</h1><p>93 PDFs preserved · 90 canonical entries · 3 earlier covered versions linked without double counting.</p><p class="note">AI-assisted research drafts. Human scientific, priority and authorship review is required. Proof/disproof labels apply only to the exact recorded scope; internal AI reviews are not external peer review.</p><p><a href="README.md">English</a> · <a href="README.zh-CN.md">中文</a> · <a href="SEMANTIC_DEDUPLICATION.md">Semantic relations</a> · <a href="reproducibility/README.md">Reproduction</a></p><input id="q" placeholder="Search topic, model, full claim, ID, limitations"><select id="category"><option value="">All four classes</option><option value="proofs">Proof / 证明</option><option value="disproofs">Disproof / 反证</option><option value="partial-results">Partial result / 部分结果</option><option value="computational-papers">Computational result / 计算结果</option></select><label><input id="versions" type="checkbox" style="width:auto"> Include earlier covered versions</label><p id="count"></p><table><thead><tr><th>Project / topic</th><th>Recorded scope and limitations</th><th>Original question / files</th></tr></thead><tbody id="rows"></tbody></table><script>const data=DATA;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const link=(p,t)=>'<a href="'+esc(p)+'">'+esc(t)+'</a>';function render(){const q=document.querySelector('#q').value.toLowerCase(),c=document.querySelector('#category').value,v=document.querySelector('#versions').checked;const a=data.projects.filter(x=>(v||x.counted_as_distinct)&&(!c||x.category===c)&&JSON.stringify(x).toLowerCase().includes(q));document.querySelector('#count').textContent=a.length+' displayed · '+data.canonical_entries+' canonical entries / '+data.stored_manuscripts+' stored manuscripts';document.querySelector('#rows').innerHTML=a.map(x=>'<tr><td><b>'+esc(x.title)+'</b><p class="muted">'+esc(x.id)+' · '+esc(x.series)+'</p><span class="badge">'+esc(x.category)+'</span>'+(!x.counted_as_distinct?'<p>Covered earlier scope. Canonical: '+link('projects/'+x.canonical_id,x.canonical_id)+'</p>':'')+'</td><td><details><summary>Expand full scientific statement</summary><p><b>Background:</b> '+esc(x.background)+'</p><p><b>Original question:</b> '+esc(x.original_question)+'</p><pre>'+esc(x.claim_statement)+'</pre><p><b>Proposed contribution:</b> '+esc(x.novelty)+'</p><p><b>Limitations:</b> '+esc(x.limitations)+'</p><p>'+esc(x.relationship_note||'')+'</p><p>'+esc(x.literature_note||'')+'</p></details></td><td><b>'+esc(x.original_status)+'</b><p>'+esc(x.release_status)+'</p>'+link(x.pdf,'PDF')+' · '+link('projects/'+x.id,'Code / sources')+(x.reproduction_guides||[]).map(g=>'<p>'+link('projects/'+x.id+'/'+g,'Replay guide')+'</p>').join('')+'</td></tr>').join('')}document.querySelector('#q').oninput=render;document.querySelector('#category').onchange=render;document.querySelector('#versions').onchange=render;render();</script></html>'''.replace('DATA',payload)
(ROOT/'catalog.html').write_text(page)
print(json.dumps({'stored':DATA['stored_manuscripts'],'canonical':DATA['canonical_entries'],'languages':len(LANG),'category_indexes':len(LANG)*len(CATEGORIES)}))
